/// <summary>
/// MPJ_5012_RebateProcess
/// </summary>
class METRebateInclusionsUpdateUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField		                    dgItemNum;

}

Method.Source:
    /// <summary>
    /// Method is overriden to get the multi select lookup for Item number field
    /// </summary>
    public void postRun()
    {
        Query   query       = new Query(queryStr(InventTable));

        QueryBuildDataSource    qbds_InventTable = query.dataSourceTable(tableNum(InventTable));
        qbds_InventTable.addSelectionField(fieldNum(InventTable,ItemId),SelectionField::Database);
        qbds_InventTable.addSelectionField(fieldNum(InventTable,NameAlias),SelectionField::Database);
        qbds_InventTable.addSelectionField(fieldNum(InventTable,ModifiedDateTime),SelectionField::Database);

        qbds_InventTable.addOrderByField(fieldNum(InventTable,ModifiedDateTime),SortOrder::Descending);

        container selectedFields = [tableNum(InventTable), fieldNum(InventTable, ItemId)];
 
        SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), dgItemNum.control(), query, false, selectedFields);
    }

    /// <summary>
    /// Method is overriden to get the Contract fields and register Lookup method
    /// </summary>
    public void postBuild()
    {        
        METRebateInclusionsUpdateContract   contract	=   this.dataContractObject() as METRebateInclusionsUpdateContract;

        dgItemNum	= this.bindInfo().getDialogField(contract, methodStr(METRebateInclusionsUpdateContract, parmItemId));

        dgItemNum.value("@SYS4004248");

        dgItemNum.lookupButton(FormLookupButton::Always);
    }
